const cate = env.get("category", "");const page = Number(env.get("page", 1) || 1);const base = env.baseUrl;
let listUrl;
if (!cate || cate === "/") { listUrl = base + "/tv/47.html"; }
else if (page <= 1) { listUrl = base + "/tv/" + cate + ".html"; }
else { listUrl = base + "/tv/" + cate + "/page/" + page + ".html"; }
const html = await req(listUrl);const $ = kitty.load(html);const items = [];
$("a.cover-img").each(function () {const $a = $(this);const href = $a.attr("href") || "";const m = href.match(/\/video\/(\d+)\.html/);if (m && items.length < 40) {const id = m[1];const title = $a.attr("title") || "";const img = $a.find("img").first();const cover = img.attr("data-original") || img.attr("data-src") || img.attr("src") || "";const key = "/video/" + id + "/";if (title && !items.some(x => x.id === key)) {let remark = "";const tag = $a.find(".pic-tag").first().text().trim();if (tag) remark = tag;items.push({ id: key, title, cover, remark });}}});
if (!cate || cate === "/") {return { type: "complex", data: [{ type: "card", title: "AI漫剧", videos: items }] };}
return items;
